//! Parity tests against the Go original (`github.com/junhinhow/charm-store`).
//!
//! The golden file is generated by the Go program in
//! `reference/go/charm-store/cmd/parity`:
//!
//! ```text
//! cargo run -p charm-parity --bin parity -- gen \
//!     crates/charm-store/tests/golden/store.txt -- \
//!     go -C reference/go/charm-store run ./cmd/parity
//! ```
//!
//! The Rust transcript below follows the Go program line by line.

use std::fmt::Write as _;
use std::sync::{Arc, Mutex};

use charm_parity::assert_golden;
use charm_store::{select, JsonCodec, Store};
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct Estado {
    nome: String,
    itens: Vec<String>,
}

type Log = Arc<Mutex<String>>;

fn new_log() -> Log {
    Arc::new(Mutex::new(String::new()))
}

fn flush(log: &Log, out: &mut String) {
    out.push_str(&std::mem::take(&mut *log.lock().unwrap()));
}

fn notificacoes(out: &mut String) {
    let log = new_log();
    let sink = Arc::clone(&log);
    let s = Store::new(0);
    let cancelar = s.subscribe(move |v: i32| {
        let _ = writeln!(sink.lock().unwrap(), "notify:{v}");
    });

    s.set(1);
    s.set(1);
    s.update(|v| v + 1);
    flush(&log, out);
    let _ = writeln!(
        out,
        "get={} history={} canUndo={} canRedo={}",
        s.get(),
        s.history(),
        s.can_undo(),
        s.can_redo()
    );

    let undo = s.undo();
    flush(&log, out);
    let _ = writeln!(out, "undo={undo}");
    let _ = writeln!(
        out,
        "get={} history={} canRedo={}",
        s.get(),
        s.history(),
        s.can_redo()
    );

    let redo = s.redo();
    flush(&log, out);
    let _ = writeln!(out, "redo={redo}");
    let _ = writeln!(out, "get={} canUndo={}", s.get(), s.can_undo());

    s.set(5);
    flush(&log, out);
    let _ = writeln!(out, "canRedo={}", s.can_redo());

    cancelar();
    cancelar();
    s.set(6);
    s.notify();
    flush(&log, out);
    let _ = writeln!(out, "get={} history={}", s.get(), s.history());
}

fn historico(out: &mut String) {
    let s = Store::new(0);
    s.set_history_limit(2);
    for i in 1..=4 {
        s.set(i);
    }
    let _ = writeln!(out, "history={}", s.history());
    for _ in 0..3 {
        let undo = s.undo();
        let _ = writeln!(out, "undo={undo} get={}", s.get());
    }
    let redo = s.redo();
    let _ = writeln!(out, "redo={redo} get={}", s.get());
    s.set_history_limit(0);
    let _ = writeln!(out, "history={}", s.history());
}

fn derivado(out: &mut String) {
    let log = new_log();
    let origem = Store::new(0);
    let dobro = select(&origem, |v: i32| v * 2);
    let sink = Arc::clone(&log);
    let _cancelar = dobro.subscribe(move |v: i32| {
        let _ = writeln!(sink.lock().unwrap(), "dobro:{v}");
    });
    origem.set(1);
    origem.set(1);
    origem.set(3);
    flush(&log, out);
    let _ = writeln!(
        out,
        "dobro={} history={} canUndo={}",
        dobro.get(),
        dobro.history(),
        dobro.can_undo()
    );
    let undo = dobro.undo();
    let redo = dobro.redo();
    let _ = writeln!(out, "undo={undo} redo={redo}");
    let _ = writeln!(out, "dobro={}", dobro.get());

    let sink = Arc::clone(&log);
    let lista = Store::new(vec!["a".to_string()]);
    let tamanho = select(&lista, |v: Vec<String>| v.len());
    let _cancelar = tamanho.subscribe(move |v: usize| {
        let _ = writeln!(sink.lock().unwrap(), "tamanho:{v}");
    });
    lista.set(vec!["b".to_string()]);
    lista.set(vec!["b".to_string(), "c".to_string()]);
    flush(&log, out);
    let _ = writeln!(out, "tamanho={}", tamanho.get());
}

fn snapshot(out: &mut String) {
    let log = new_log();
    let origem = Store::new(Estado::default());
    origem.set(Estado {
        nome: "primeiro".to_string(),
        itens: vec!["a".to_string()],
    });
    origem.set(Estado {
        nome: "segundo".to_string(),
        itens: vec!["b".to_string(), "c".to_string()],
    });
    let data = origem.snapshot(&JsonCodec);
    let _ = writeln!(
        out,
        "snapshot err={} data={}",
        data.is_err(),
        String::from_utf8_lossy(data.as_deref().unwrap_or_default())
    );
    let data = data.unwrap_or_default();

    let destino = Store::new(Estado {
        nome: "antigo".to_string(),
        itens: Vec::new(),
    });
    destino.set(Estado {
        nome: "novo".to_string(),
        itens: Vec::new(),
    });
    let sink = Arc::clone(&log);
    let _cancelar = destino.subscribe(move |e: Estado| {
        let _ = writeln!(
            sink.lock().unwrap(),
            "restore-notify:{}:{}",
            e.nome,
            e.itens.join(",")
        );
    });

    let result = destino.restore(&JsonCodec, &data);
    flush(&log, out);
    let e = destino.get();
    let _ = writeln!(
        out,
        "restore err={} nome={} itens={} history={} canUndo={}",
        result.is_err(),
        e.nome,
        e.itens.join(","),
        destino.history(),
        destino.can_undo()
    );

    let result = destino.restore(&JsonCodec, &data);
    flush(&log, out);
    let _ = writeln!(out, "restore igual err={}", result.is_err());

    let result = destino.restore(&JsonCodec, b"{");
    let e = destino.get();
    let _ = writeln!(
        out,
        "restore invalido err={} nome={}",
        result.is_err(),
        e.nome
    );

    let inteiro = Store::new(0);
    let dados = inteiro.snapshot(&JsonCodec).unwrap_or_default();
    let _ = writeln!(out, "inteiro={}", String::from_utf8_lossy(&dados));
}

fn transcript() -> String {
    let mut out = String::new();
    notificacoes(&mut out);
    historico(&mut out);
    derivado(&mut out);
    snapshot(&mut out);
    out
}

#[test]
fn transcript_matches_the_go_original() {
    assert_golden("store", &transcript());
}
